package view;
import dao.admin.*;import java.awt.*;import javax.swing.*;import javax.swing.table.DefaultTableModel;import model.auth.AuthenticatedSession;import view.component.UIStyle;
final class AdminPanel extends JPanel{private final AuthenticatedSession session;private final String module;private final AdminDAO dao=new AdminDAO();private final JTextField search=new JTextField();private final JLabel count=new JLabel(" ");private final JPanel tableHost=new JPanel(new BorderLayout());AdminPanel(AuthenticatedSession s,String m){session=s;module=m;setLayout(new BorderLayout(0,16));setBackground(MainFrame.PAGE);setBorder(BorderFactory.createEmptyBorder(25,28,30,28));add(header(),BorderLayout.NORTH);add(body(),BorderLayout.CENTER);load();}private JPanel header(){JPanel p=new JPanel(new BorderLayout());p.setOpaque(false);JPanel l=new JPanel();l.setOpaque(false);l.setLayout(new BoxLayout(l,BoxLayout.Y_AXIS));JLabel t=new JLabel(module);t.setFont(new Font("Segoe UI",Font.BOLD,25));t.setForeground(MainFrame.TEXT);JLabel d=new JLabel(description());d.setForeground(MainFrame.MUTED);l.add(t);l.add(d);JButton refresh=new JButton("Làm mới");UIStyle.secondaryButton(refresh);refresh.addActionListener(e->load());p.add(l,BorderLayout.WEST);p.add(refresh,BorderLayout.EAST);return p;}private String description(){return switch(module){case "Phân quyền"->"Tra cứu vai trò và các quyền đang được cấp.";case "Thiết bị"->"Theo dõi thiết bị, vị trí và tình trạng vận hành.";case "Đánh giá nhân viên"->"Tra cứu kết quả đánh giá theo nhân viên và kỳ đánh giá.";case "Cấu hình hệ thống"->"Tra cứu các tham số cấu hình đang áp dụng.";case "Nhật ký hệ thống"->"Theo dõi lịch sử thao tác và sự kiện bảo mật.";case "Thông báo"->"Theo dõi thông báo đã tạo, trạng thái và kênh gửi.";default->"Tổng hợp các chỉ số vận hành của phòng khám.";};}private JPanel body(){JPanel p=new JPanel(new BorderLayout(0,12));p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(MainFrame.BORDER),BorderFactory.createEmptyBorder(16,16,16,16)));JPanel bar=new JPanel(new BorderLayout(10,0));bar.setOpaque(false);search.setPreferredSize(new Dimension(420,36));search.putClientProperty("JTextField.placeholderText","Tìm kiếm dữ liệu...");bar.add(search,BorderLayout.CENTER);bar.add(count,BorderLayout.EAST);p.add(bar,BorderLayout.NORTH);tableHost.setBackground(Color.WHITE);p.add(tableHost,BorderLayout.CENTER);search.addActionListener(e->load());return p;}private void load(){new SwingWorker<AdminDAO.Result,Void>(){protected AdminDAO.Result doInBackground(){return dao.find(module,search.getText());}protected void done(){try{AdminDAO.Result x=get();DefaultTableModel m=new DefaultTableModel(x.columns(),0){public boolean isCellEditable(int r,int c){return false;}};for(Object[] row:x.rows())m.addRow(row);JTable t=new JTable(m);UIStyle.table(t);t.setAutoCreateRowSorter(true);tableHost.removeAll();tableHost.add(new JScrollPane(t),BorderLayout.CENTER);count.setText(x.rows().size()+" bản ghi");tableHost.revalidate();tableHost.repaint();}catch(Exception e){UIStyle.showError(AdminPanel.this,e.getCause()==null?e.getMessage():e.getCause().getMessage());}}}.execute();}}
